# Arch's default Lua is 5.5; here it is 5.4, and the 5.4 config is made on the last line.
sub ./build/luarocks-admin ./build/config-5.5.lua => ./build/luarocks-admin
# lua-luarocks has the Lua files, luarocks the programs. Arch's configure picks Lua 5.5 and luarocks drops that folder; here
# it picks 5.3 and the two would own the same files.
sub rm -rf "$pkgdir/usr/share/lua/5.5" => rm -rf "$pkgdir/usr/share/lua"
